function chainEdges(edges){const next=new Map();for(const[e1,e2]of edges){const k=e1.join(',');if(!next.has(k))next.set(k,[]);next.get(k).push(e2);}const loops=[];let guard=0;while(next.size&&guard++<2000000){const firstKey=next.keys().next().value,start=firstKey.split(',').map(Number),loop=[start];let cur=start,safety=0;while(safety++<1000000){const k=cur.join(','),arr=next.get(k);if(!arr||!arr.length)break;const n=arr.pop();if(!arr.length)next.delete(k);cur=n;loop.push(cur);if(cur[0]===start[0]&&cur[1]===start[1])break;}if(loop.length>=4)loops.push(loop);}return loops;}

